document.addEventListener('click',event=>{const nav=event.target.closest('[data-cal-nav]'),edit=event.target.closest('[data-edit-event]');if(nav){event.preventDefault();calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+Number(nav.dataset.calNav),1);render()}if(edit){event.preventDefault();event.stopImmediatePropagation();enhancedEventForm(data.events.find(item=>String(item.id)===String(edit.dataset.editEvent)))}},true);
async function enhanceEventAvailability(){const editButton=$('[data-edit-event]');if(!editButton||$('#event-availability')||editButton.dataset.availabilityLoading)return;editButton.dataset.availabilityLoading='true';try{const [result,helperResult]=await Promise.all([apiRequest(`/api/events/${editButton.dataset.editEvent}/responses`),apiRequest('/api/guest-helpers')]),groups={yes:[],maybe:[],no:[]};guestHelpers=helperResult.helpers;for(const response of result.responses)(groups[response.response]||groups.maybe).push(response);const guestOffers=guestHelpers.filter(item=>String(item.eventId)===String(editButton.dataset.editEvent)&&item.status!=='Declined'&&!item.archivedAt).map(item=>({id:item.id,memberName:item.name,call:item.callsign,mobilePhone:item.phone,updatedAt:item.updatedAt||item.createdAt,group:item.group,guest:true,status:item.status})),availableItems=[...groups.yes,...guestOffers];const available=$('[data-event-available]'),guestCount=$('[data-event-guests]');if(available)available.textContent=availableItems.length;if(guestCount)guestCount.textContent=guestOffers.length;const personList=(items,empty)=>items.length?items.map(item=>`<div class="activity-row" ${item.guest?`data-guest-helper="${safe(item.id)}" title="Open guest-helper record"`:''}><div class="person-avatar">${safe(initials(item.memberName))}</div><div><p>${safe(item.memberName)} ${item.guest?'<span class="badge sent">Guest helper</span>':''}</p><small>${safe(item.call||'')}${item.guest&&item.group?' · '+safe(item.group):''}${item.guest&&item.status?' · '+safe(item.status):''}${item.mobilePhone?' · '+safe(item.mobilePhone):''}</small></div><small>${item.updatedAt?new Date(item.updatedAt).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}):''}</small></div>`).join(''):`<p class="subtext">${empty}</p>`;const actions=$('#modal-content .modal-actions');actions.insertAdjacentHTML('beforebegin',`<div class="card" id="event-availability" style="padding:16px;margin-top:16px"><div class="public-title"><div><strong>Staffing availability</strong><p class="subtext">${result.responses.length} member response${result.responses.length===1?'':'s'} · ${guestOffers.length} guest helper offer${guestOffers.length===1?'':'s'}</p></div></div><details open><summary><strong>Available (${availableItems.length})</strong></summary>${personList(availableItems,'No members or guest helpers have offered availability.')}</details><details><summary><strong>Maybe (${groups.maybe.length})</strong></summary>${personList(groups.maybe,'No tentative responses.')}</details><details><summary><strong>Can’t help (${groups.no.length})</strong></summary>${personList(groups.no,'No unavailable responses.')}</details></div>`)}catch(error){const actions=$('#modal-content .modal-actions');actions?.insertAdjacentHTML('beforebegin',`<p class="auth-error show" id="event-availability">${safe(error.message)}</p>`)}}
const eventAvailabilityObserver=new MutationObserver(enhanceEventAvailability);eventAvailabilityObserver.observe(document.body,{childList:true,subtree:true});
const availabilityCollapseObserver=new MutationObserver(()=>{const roster=$('#event-availability');if(!roster||roster.dataset.collapsed)return;roster.dataset.collapsed='true';$$('details',roster).forEach(section=>section.removeAttribute('open'))});availabilityCollapseObserver.observe(document.body,{childList:true,subtree:true});
function publicPortal(){$('.app-shell').style.display='none';document.body.insertAdjacentHTML('beforeend',`<div class="public-shell" id="public-shell"><nav class="public-nav"><div class="brand"><img class="brand-logo" src="${safe(branding.logo)}" alt="Organisation logo"><div><strong>${safe(branding.name)}</strong><small>${safe(branding.subtitle)}</small></div></div><button class="portal-close" id="portal-close">← Staff area</button></nav><section class="public-hero"><div class="eyebrow" style="color:white">Member availability</div><h1>Help us keep Hampshire connected.</h1><p>View upcoming events and let the team know whether you’re available to support communications.</p></section><main class="public-content"><div class="public-card"><div class="public-title"><div><h2>Upcoming events</h2><p class="subtext">Select your availability for each event.</p></div><span class="badge active">${data.events.length} published</span></div><div class="public-events">${data.events.map(e=>`<article class="public-event"><div class="date-badge"><strong>${e.date.split(' ')[0]}</strong><small>${e.date.split(' ')[1]}</small></div><h3>${e.title}</h3><small>⌖ ${e.location}</small><p>${e.desc}</p><div class="response-buttons"><button data-rsvp="yes" data-e="${e.id}">✓ I can help</button><button data-rsvp="maybe" data-e="${e.id}">Maybe</button><button data-rsvp="no" data-e="${e.id}">Can't help</button></div></article>`).join('')}</div></div></main></div>`);$('#portal-close').onclick=()=>{$('#public-shell').remove();$('.app-shell').style.display='block'};$$('[data-rsvp]').forEach(b=>b.onclick=()=>rsvp(b.dataset.e,b.dataset.rsvp))}
async function memberPortal(){document.querySelector('#public-shell')?.remove();$('#app-shell').hidden=true;$('#app-shell').style.display='none';const result=await apiRequest('/api/my-events'),responses=new Map(result.responses.map(r=>[String(r.eventId),r.response])),member=data.members.find(m=>String(m.id)===String(signedInUser.memberId));document.body.insertAdjacentHTML('beforeend',`<div class="public-shell" id="public-shell"><nav class="public-nav"><div class="brand"><img class="brand-logo" src="${safe(branding.logo)}" alt="Organisation logo"><div><strong>${safe(branding.name)}</strong><small>Member portal</small></div></div><div><span style="margin-right:16px">${safe(member?.name||signedInUser.name)}</span><button class="portal-close" id="member-logout">Sign out</button></div></nav><section class="public-hero"><div class="eyebrow" style="color:white">Your member portal</div><h1>Welcome, ${safe((member?.name||signedInUser.name).split(' ')[0])}.</h1><p>Tell the group which events you can support. Your choices are saved against your member record.</p></section><main class="public-content"><div class="public-card"><div class="public-title"><div><h2>Your upcoming events</h2><p class="subtext">You can change your response at any time.</p></div><span class="badge active">${data.events.length} events</span></div><div class="public-events">${data.events.map(e=>{const current=responses.get(String(e.id));return `<article class="public-event"><div class="date-badge"><strong>${e.date.split(' ')[0]}</strong><small>${e.date.split(' ')[1]}</small></div><h3>${safe(e.title)}</h3><small>⌖ ${safe(e.location)}</small><p>${safe(e.desc)}</p>${current?`<p><strong>Current response: ${current==='yes'?'I can help':current==='maybe'?'Maybe':"Can't help"}</strong></p>`:''}<div class="response-buttons"><button data-member-rsvp="yes" data-e="${e.id}" ${current==='yes'?'class="selected"':''}>✓ I can help</button><button data-member-rsvp="maybe" data-e="${e.id}" ${current==='maybe'?'class="selected"':''}>Maybe</button><button data-member-rsvp="no" data-e="${e.id}" ${current==='no'?'class="selected"':''}>Can't help</button></div></article>`}).join('')}</div></div></main></div>`);$('#member-logout').onclick=async()=>{await apiRequest('/api/auth/logout',{method:'POST'});signedInUser=null;$('#public-shell').remove();showAuth(false)};$$('[data-member-rsvp]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await apiRequest('/api/my-events',{method:'POST',body:JSON.stringify({eventId:button.dataset.e,response:button.dataset.memberRsvp})});await memberPortal()}catch(error){button.disabled=false;alert(error.message)}})}
function rsvp(id,response){showModal(`<h2>Record your availability</h2><p class="intro">Your response will be visible to the event coordinator.</p><form id="rsvp-form"><div class="form-grid"><div class="field full"><label>Your name</label><input name="name" required placeholder="Full name"></div><div class="field full"><label>Callsign</label><input name="call" required placeholder="e.g. M7ABC"></div><div class="field full"><label>Notes for the coordinator (optional)</label><textarea rows="3" placeholder="Times, equipment or access notes"></textarea></div></div><div class="modal-actions"><button type="button" class="secondary-btn" data-cancel>Cancel</button><button class="primary-btn">Submit response</button></div></form>`);$('#rsvp-form').onsubmit=e=>{e.preventDefault();if(response==='yes'){let ev=data.events.find(x=>x.id==id);ev.yes++;save()}closeModal();toast('Availability recorded','Thank you — the coordinator can now see your response.')}}
async function apiRequest(url,options={}){const response=await fetch(url,{headers:{'Content-Type':'application/json'},...options});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'The request could not be completed.');return body}
async function loadUsers(){const result=await apiRequest('/api/users');systemUsers=result.users}
async function loadMembers(){let result=await apiRequest('/api/members');if(!result.members.length&&data.members.length&&signedInUser?.role==='admin')result=await apiRequest('/api/members/import',{method:'POST',body:JSON.stringify({members:data.members.map(normaliseMember)})});if(result.members.length){data.members=result.members;localStorage.setItem('raynet-crm-data',JSON.stringify(data))}}
async function loadEvents(){let result=await apiRequest('/api/events');if(!result.events.length&&data.events.length&&signedInUser?.role==='admin')result=await apiRequest('/api/events/import',{method:'POST',body:JSON.stringify({events:data.events})});if(result.events.length||!data.events.length){data.events=result.events;localStorage.setItem('raynet-crm-data',JSON.stringify(data))}}
function addUserForm(){showModal(`<h2>Create a user account</h2><p class="intro">They can sign in immediately using the temporary password.</p><form id="user-form"><div class="form-grid"><div class="field full"><label>Full name</label><input name="name" required autocomplete="off"></div><div class="field full"><label>Email address</label><input name="email" type="email" required autocomplete="off"></div><div class="field"><label>Access role</label><select name="role"><option value="coordinator">Coordinator</option><option value="viewer">Viewer</option><option value="admin">Administrator</option></select></div><div class="field"><label>Temporary password</label><input name="password" type="password" minlength="10" required autocomplete="new-password"></div><div class="field full"><div class="auth-hint">Use at least 10 characters. Share the temporary password securely and separately from the login email.</div></div></div><p class="auth-error" id="user-error"></p><div class="modal-actions"><button type="button" class="secondary-btn" data-cancel>Cancel</button><button class="primary-btn">Create account</button></div></form>`);$('#user-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await apiRequest('/api/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await loadUsers();closeModal();render();toast('Account created','The new user can now sign in.')}catch(error){$('#user-error').textContent=error.message;$('#user-error').classList.add('show');button.disabled=false}}}
function editUserForm(id){const user=systemUsers.find(u=>u.id===id);if(!user)return;const ownAccount=user.id===signedInUser.id;showModal(`<h2>Edit user</h2><p class="intro">Update ${safe(user.name)}’s account details and access level.</p><form id="edit-user-form"><div class="form-grid"><div class="field full"><label>Full name</label><input name="name" value="${safe(user.name)}" maxlength="100" required></div><div class="field full"><label>Email address</label><input name="email" type="email" value="${safe(user.email)}" required></div><div class="field full"><label>Access role</label><select name="role" ${ownAccount?'disabled':''}><option value="admin" ${user.role==='admin'?'selected':''}>Administrator</option><option value="coordinator" ${user.role==='coordinator'?'selected':''}>Coordinator</option><option value="viewer" ${user.role==='viewer'?'selected':''}>Viewer</option></select>${ownAccount?'<small class="subtext">Your own administrator role cannot be changed here.</small>':''}</div><div class="field full"><div class="auth-hint"><strong>Administrator:</strong> full access, including users and branding.<br><strong>Coordinator:</strong> manages CRM records and events.<br><strong>Viewer:</strong> read-only access.</div></div></div><p class="auth-error" id="edit-user-error"></p><div class="modal-actions"><button type="button" class="secondary-btn" data-cancel>Cancel</button><button class="primary-btn">Save changes</button></div></form>`);$('#edit-user-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;const values=Object.fromEntries(new FormData(e.target));if(ownAccount)delete values.role;try{const result=await apiRequest('/api/users/'+id,{method:'PATCH',body:JSON.stringify(values)});const index=systemUsers.findIndex(u=>u.id===id);systemUsers[index]=result.user;if(ownAccount){signedInUser=result.user;$('#profile-name').textContent=result.user.name;$('#profile-avatar').textContent=initials(result.user.name)}closeModal();render();toast('User updated',`${result.user.name}’s account has been saved.`)}catch(error){$('#edit-user-error').textContent=error.message;$('#edit-user-error').classList.add('show');button.disabled=false}}}
function resetPasswordForm(id){const user=systemUsers.find(u=>u.id===id);showModal(`<h2>Reset password</h2><p class="intro">Set a new temporary password for ${user.name}.</p><form id="reset-form"><div class="field"><label>New temporary password</label><input name="password" type="password" minlength="10" required autocomplete="new-password"></div><p class="auth-error" id="reset-error"></p><div class="modal-actions"><button type="button" class="secondary-btn" data-cancel>Cancel</button><button class="primary-btn">Update password</button></div></form>`);$('#reset-form').onsubmit=async e=>{e.preventDefault();try{await apiRequest('/api/users/'+id,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Password updated','The user can sign in with their new password.')}catch(error){$('#reset-error').textContent=error.message;$('#reset-error').classList.add('show')}}}
function initBrandingForm(){const form=$('#branding-form');if(!form)return;let draftLogo=branding.logo;const preview=()=>{$('#branding-card-name').textContent=form.elements.name.value;$('#branding-card-subtitle').textContent=form.elements.subtitle.value;$('#branding-preview-card').style.background=form.elements.primary.value;$('.branding-preview-accent').style.background=form.elements.accent.value};['name','subtitle','primary','accent'].forEach(name=>form.elements[name].addEventListener('input',preview));const sync=(picker,text)=>{picker.oninput=()=>{text.value=picker.value;preview()};text.oninput=()=>{if(/^#[0-9a-f]{6}$/i.test(text.value))picker.value=text.value;preview()}};sync($('#primary-picker'),$('#primary-text'));sync($('#accent-picker'),$('#accent-text'));$('#branding-logo-input').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.size>1500000){$('#branding-error').textContent='Please choose a logo smaller than 1.5 MB.';$('#branding-error').classList.add('show');return}const reader=new FileReader();reader.onload=()=>{draftLogo=reader.result;$('#branding-logo-preview').src=draftLogo;$('#branding-card-logo').src=draftLogo};reader.readAsDataURL(file)};$('#branding-reset').onclick=()=>{form.elements.name.value='South East Hampshire RAYNET';form.elements.shortName.value='SE Hants RAYNET';form.elements.subtitle.value='Member CRM';form.elements.primary.value='#07175e';form.elements.accent.value='#e0001b';$('#primary-picker').value='#07175e';$('#accent-picker').value='#e0001b';draftLogo='/assets/sehants-raynet-logo.png';$('#branding-logo-preview').src=draftLogo;$('#branding-card-logo').src=draftLogo;preview()};form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const values=Object.fromEntries(new FormData(form));values.logo=draftLogo;const result=await apiRequest('/api/branding',{method:'PUT',body:JSON.stringify(values)});branding=result.branding;applyBranding();render();toast('Branding saved','The new identity is now applied across the CRM.')}catch(error){$('#branding-error').textContent=error.message;$('#branding-error').classList.add('show');button.disabled=false}};preview()}
function upgradeMemberForm(form){if(!form||form.dataset.membershipFields)return;const oldRole=form.querySelector('[name="role"]');if(!oldRole)return;form.dataset.membershipFields='true';const existing=normaliseMember(data.members.find(m=>m.name===form.elements.name?.value)),current=existing||{membershipType:'Member',committeePositions:[]};const linked=existing?systemUsers.find(u=>String(u.memberId)===String(existing.id)):null;const field=oldRole.closest('.field');field.innerHTML=`<label>Membership type</label><select name="membershipType"><option ${current.membershipType==='Member'?'selected':''}>Member</option><option ${current.membershipType==='Committee member'?'selected':''}>Committee member</option></select>`;field.insertAdjacentHTML('afterend',`<div class="field full committee-position-field"><label>Committee positions</label><div class="committee-choices">${membershipSettings.committeePositions.map(position=>`<label class="committee-choice"><input type="checkbox" data-committee-position value="${safe(position)}" ${current.committeePositions.includes(position)?'checked':''}>${safe(position)}</label>`).join('')}</div><small class="subtext">Select every position held by this member.</small><input type="hidden" name="committeePositionsJson"></div>`);form.querySelector('.form-grid').insertAdjacentHTML('beforeend',`<div class="form-section"><h3>Portal access</h3><p>Create and manage this member’s login from the same record.</p></div><label class="check-option field full"><input type="checkbox" name="portalAccess" ${linked||!existing?'checked':''}><span><strong>Give this member login access</strong><small>They can sign in, respond to events and view their own commitments.</small></span></label><div class="field portal-access-field"><label>System access</label><select name="accessRole"><option value="member" ${!linked||linked.role==='member'?'selected':''}>Member portal</option><option value="viewer" ${linked?.role==='viewer'?'selected':''}>Staff viewer</option><option value="coordinator" ${linked?.role==='coordinator'?'selected':''}>Coordinator</option><option value="admin" ${linked?.role==='admin'?'selected':''}>Administrator</option></select></div><div class="field portal-access-field"><label>${linked?'New password (optional)':'Temporary password'}</label><input name="temporaryPassword" type="password" minlength="10" autocomplete="new-password"><small class="subtext">${linked?'Leave blank to keep the current password.':'At least 10 characters.'}</small></div>`);const type=form.elements.membershipType,container=form.querySelector('.committee-position-field'),portal=form.elements.portalAccess;const toggle=()=>{const committee=type.value==='Committee member';container.style.display=committee?'block':'none';if(!committee)container.querySelectorAll('[data-committee-position]').forEach(box=>box.checked=false)};const togglePortal=()=>{$$('.portal-access-field',form).forEach(el=>el.style.display=portal.checked?'block':'none');form.elements.temporaryPassword.required=portal.checked&&!linked};type.onchange=toggle;portal.onchange=togglePortal;toggle();togglePortal();form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const values=Object.fromEntries(new FormData(form));values.portalAccess=portal.checked;values.committeePositions=[...form.querySelectorAll('[data-committee-position]:checked')].map(box=>box.value);values.renewal=values.renewal?new Date(values.renewal+'T12:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—';['ownVehicle','canWalkDistance','canCarryEquipment','accessiblePlacement'].forEach(k=>values[k]=form.elements[k].checked);values.email=values.raynetEmail||values.personalEmail;values.phone=values.mobilePhone||values.homePhone;delete values.committeePositionsJson;const result=await apiRequest(existing?'/api/members/'+existing.id:'/api/members',{method:existing?'PATCH':'POST',body:JSON.stringify(values)});if(existing)Object.assign(existing,result.member);else data.members.unshift(result.member);if(signedInUser.role==='admin')await loadUsers();localStorage.setItem('raynet-crm-data',JSON.stringify(data));closeModal();render();toast(existing?'Member updated':'Member added',`${result.member.name} and their access have been saved.`)}catch(error){button.disabled=false;toast('Could not save member',error.message)}}}
function addMemberLinkField(form){if(!form||form.dataset.memberLink)return;form.dataset.memberLink='true';const currentUser=systemUsers.find(u=>u.email===form.elements.email?.value);const options=data.members.map(normaliseMember).filter(m=>!systemUsers.some(u=>u.id!==currentUser?.id&&String(u.memberId)===String(m.id))).map(m=>`<option value="${m.id}" ${String(currentUser?.memberId)===String(m.id)?'selected':''}>${safe(m.name)} (${safe(m.call)})</option>`).join('');form.querySelector('.form-grid').insertAdjacentHTML('beforeend',`<div class="field full"><label>Linked member record</label><select name="memberId"><option value="">No linked member</option>${options}</select><small class="subtext">Links this login to the person’s membership profile.</small></div>`)}
function addNextOfKinFields(form){if(!form||form.dataset.nextOfKin)return;form.dataset.nextOfKin='true';const member=normaliseMember(data.members.find(m=>m.name===form.elements.name?.value))||{};const deploymentSection=[...form.querySelectorAll('.form-section')].find(section=>section.textContent.includes('Deployment profile'));if(!deploymentSection)return;deploymentSection.insertAdjacentHTML('beforebegin',`<div class="form-section"><h3>Next of kin</h3><p>Emergency contact information for this member.</p></div><div class="field"><label>Next-of-kin name</label><input name="nextOfKinName" value="${safe(member.nextOfKinName||'')}"></div><div class="field"><label>Relationship</label><input name="nextOfKinRelationship" value="${safe(member.nextOfKinRelationship||'')}"></div><div class="field"><label>Next-of-kin phone</label><input name="nextOfKinPhone" type="tel" value="${safe(member.nextOfKinPhone||'')}"></div><div class="field full"><label>Emergency information</label><textarea name="emergencyNotes" rows="2">${safe(member.emergencyNotes||'')}</textarea></div>`)}
function editOwnProfile(member){showModal(`<h2>My profile</h2><p class="intro">Update your contact, emergency and deployment details. Membership and access settings are managed by an administrator.</p><form id="my-profile-form"><div class="form-grid"><div class="form-section"><h3>Contact details</h3></div><div class="field"><label>RAYNET email</label><input value="${safe(member.raynetEmail||'')}" disabled><small class="subtext">Ask an administrator to change this.</small></div><div class="field"><label>Personal email</label><input name="personalEmail" type="email" value="${safe(member.personalEmail||'')}"></div><div class="field"><label>Mobile phone</label><input name="mobilePhone" type="tel" value="${safe(member.mobilePhone||'')}"></div><div class="field"><label>Home phone</label><input name="homePhone" type="tel" value="${safe(member.homePhone||'')}"></div><div class="field full"><label>Postal address</label><textarea name="address" rows="3">${safe(member.address||'')}</textarea></div><div class="form-section"><h3>Next of kin</h3></div><div class="field"><label>Next-of-kin name</label><input name="nextOfKinName" value="${safe(member.nextOfKinName||'')}"></div><div class="field"><label>Relationship</label><input name="nextOfKinRelationship" value="${safe(member.nextOfKinRelationship||'')}"></div><div class="field"><label>Next-of-kin phone</label><input name="nextOfKinPhone" type="tel" value="${safe(member.nextOfKinPhone||'')}"></div><div class="field full"><label>Emergency information</label><textarea name="emergencyNotes" rows="2">${safe(member.emergencyNotes||'')}</textarea></div><div class="form-section"><h3>Event placement</h3></div><div class="field full"><label>Placement preference</label><select name="deployment"><option ${member.deployment==='Flexible'?'selected':''}>Flexible</option><option ${member.deployment==='Vehicle-based role required'?'selected':''}>Vehicle-based role required</option><option ${member.deployment==='Foot/mobile role preferred'?'selected':''}>Foot/mobile role preferred</option><option ${member.deployment==='Limited walking'?'selected':''}>Limited walking</option></select></div>${deploymentChecks(member)}</div><p class="auth-error" id="profile-error"></p><div class="modal-actions"><button type="button" class="secondary-btn" data-cancel>Cancel</button><button class="primary-btn">Save my profile</button></div></form>`);$('#my-profile-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=e.submitter,values=Object.fromEntries(new FormData(form));button.disabled=true;for(const field of ['ownVehicle','canWalkDistance','canCarryEquipment','accessiblePlacement'])values[field]=form.elements[field].checked;try{const result=await apiRequest('/api/my-profile',{method:'PATCH',body:JSON.stringify(values)});const index=data.members.findIndex(m=>String(m.id)===String(result.member.id));if(index>=0)data.members[index]=result.member;localStorage.setItem('raynet-crm-data',JSON.stringify(data));closeModal();toast('Profile updated','Your contact and emergency details have been saved.')}catch(error){$('#profile-error').textContent=error.message;$('#profile-error').classList.add('show');button.disabled=false}}}
function enhanceMemberPortal(){const shell=$('#public-shell');if(!shell||!signedInUser?.memberId||$('#edit-own-profile'))return;const logout=$('#member-logout');if(!logout)return;logout.insertAdjacentHTML('beforebegin','<button class="portal-close" id="edit-own-profile" style="margin-right:8px">My profile</button>');$('#edit-own-profile').onclick=async()=>{try{const result=await apiRequest('/api/my-profile');editOwnProfile(normaliseMember(result.member))}catch(error){alert(error.message)}}}
