function exportCsv(){const members=data.members.map(normaliseMember);const headings=['Name','Callsign','Membership number','RAYNET email','Personal email','Mobile phone','Home phone','Address','Membership type','Committee positions','Status','Renewal','Placement preference','Own vehicle','Can walk distance','Can carry equipment','Accessible placement','Notes'];const rows=members.map(m=>[m.name,m.call,m.membershipNumber,m.raynetEmail,m.personalEmail,m.mobilePhone,m.homePhone,m.address,m.membershipType,m.committeePositions.join('; '),m.status,m.renewal,m.deployment,m.ownVehicle,m.canWalkDistance,m.canCarryEquipment,m.accessiblePlacement,m.notes]);const quote=value=>'"'+String(value??'').replace(/"/g,'""')+'"';let csv=headings.map(quote).join(',')+'\n'+rows.map(row=>row.map(quote).join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='raynet-members.csv';a.click();toast('Export ready','The complete member register was downloaded as CSV.')}
