const baseShowAuth=showAuth;showAuth=function(setup=false){baseShowAuth(setup);if(!setup)return;const sample=$('#setup-form [name="includeSampleData"]')?.closest('label');if(!sample)return;sample.insertAdjacentHTML('beforebegin',`<details class="field full setup-database"><summary><strong>Database storage</strong> (optional)</summary><div class="form-grid"><div class="field full"><label>Storage type</label><select name="storageDriver"><option value="json">Local JSON files</option><option value="mysql">MySQL database</option></select></div><div id="setup-mysql-fields" class="form-grid field full" hidden><div class="field"><label>MySQL host</label><input name="mysqlHost" placeholder="127.0.0.1"></div><div class="field"><label>Port</label><input name="mysqlPort" type="number" value="3306" min="1" max="65535"></div><div class="field"><label>Database name</label><input name="mysqlDatabase"></div><div class="field"><label>Database user</label><input name="mysqlUser" autocomplete="username"></div><div class="field"><label>Password</label><input name="mysqlPassword" type="password" autocomplete="new-password"></div><label class="check-option field"><input name="mysqlSsl" type="checkbox"><span><strong>Require verified TLS</strong></span></label></div></div><p class="subtext">JSON is simplest for testing. Choose MySQL for a hosted installation; the connection is verified before setup completes.</p></details>`);const driver=$('#setup-form [name="storageDriver"]'),fields=$('#setup-mysql-fields');driver.onchange=()=>{fields.hidden=driver.value!=='mysql'};}
async function boot(){try{const renewalToken=new URLSearchParams(location.search).get('renewal'),[status,brandResult,publicResult,eventResult]=await Promise.all([apiRequest('/api/auth/status'),apiRequest('/api/branding'),apiRequest('/api/public-site'),apiRequest('/api/events')]);branding=brandResult.branding;publicSiteSettings=publicResult.settings;if(eventResult.events.length||!data.events.length)data.events=eventResult.events;applyBranding();if(renewalToken)return await showRenewalResponse(renewalToken);if(status.setupRequired)return showAuth(true);showPublicHome(status.user)}catch(error){$('#public-home').hidden=true;$('#auth-screen').style.display='flex';$('#auth-content').innerHTML=`<h1>Cannot reach the CRM</h1><p>${error.message}</p><div class="auth-hint">Make sure the server window is still open, then refresh this page.</div>`}}
$$('.nav-item').forEach(n=>n.onclick=()=>go(n.dataset.page));$('#modal-close').onclick=closeModal;$('#modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop')closeModal()};document.addEventListener('click',e=>{if(e.target.closest('[data-cancel]'))closeModal();const enhancedEdit=e.target.closest('[data-enhanced-edit-member]');if(enhancedEdit){enhancedEditMemberForm(enhancedEdit.dataset.enhancedEditMember);return}const memberRow=e.target.closest('[data-member]');if(memberRow){enhancedMemberDetail(memberRow.dataset.member);return}if(e.target.closest('[data-edit]')){const memberName=$('#modal-content h2')?.textContent;const member=data.members.find(m=>m.name===memberName);if(member)enhancedEditMemberForm(member.id)}});$('#quick-add').onclick=()=>showModal(`<h2>What would you like to add?</h2><p class="intro">Choose a record type to get started.</p><div class="choice-list"><button class="choice" data-quick="member"><span class="choice-icon">＋</span><span><strong>Member</strong><small>Personal, contact and membership details</small></span></button><button class="choice" data-quick="organisation"><span class="choice-icon">⌂</span><span><strong>End user</strong><small>Organisation and service contacts</small></span></button><button class="choice" data-quick="event"><span class="choice-icon">◇</span><span><strong>Event</strong><small>Publish an event and collect availability</small></span></button></div>`);document.addEventListener('click',e=>{let q=e.target.closest('[data-quick]');if(q){closeModal();({member:memberForm,organisation:orgForm,event:eventForm}[q.dataset.quick])()}});$('#open-public').onclick=()=>showPublicHome(signedInUser);$('#mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');$('#global-search').onclick=()=>{go('members');setTimeout(()=>$('#member-search').focus(),20)};$('#logout-btn').onclick=async()=>{await apiRequest('/api/auth/logout',{method:'POST'});signedInUser=null;showPublicHome(null)};paintIcons();boot();
